  document.getElementById('minus').addEventListener('click',()=>{quantity=Math.max(1,quantity-1);updateQuantity()});
  document.getElementById('addCart').addEventListener('click',()=>{
    document.getElementById('cartMessage').textContent = quantity + (quantity === 1 ? ' item added to cart' : ' items added to cart');
