  document.querySelectorAll('.radio-row').forEach(row=>row.addEventListener('click',()=>{
    document.querySelectorAll('.radio-row .radio').forEach(r=>r.classList.remove('active'));
    row.querySelector('.radio').classList.add('active');
  }));
